USE mandarin_pronunciation;
INSERT INTO level_latihan (nama_level) VALUES ('Level 1'), ('Level 2'), ('Level 3')
  ON DUPLICATE KEY UPDATE nama_level = VALUES(nama_level);

INSERT INTO kata_acuan (id_level, hanzi, pinyin)
SELECT l.id_level, x.hanzi, x.pinyin
FROM level_latihan l
JOIN (
  SELECT 'Level 1' AS level_name, '我' AS hanzi, 'wǒ' AS pinyin UNION ALL
  SELECT 'Level 1', '你', 'nǐ' UNION ALL
  SELECT 'Level 1', '好', 'hǎo' UNION ALL
  SELECT 'Level 1', '你好', 'nǐ hǎo' UNION ALL
  SELECT 'Level 1', '中国', 'zhōng guó' UNION ALL
  SELECT 'Level 2', '老师', 'lǎo shī' UNION ALL
  SELECT 'Level 2', '学校', 'xué xiào' UNION ALL
  SELECT 'Level 2', '朋友', 'péng yǒu' UNION ALL
  SELECT 'Level 3', '北京', 'běi jīng' UNION ALL
  SELECT 'Level 3', '学生', 'xué shēng'
) AS x ON x.level_name = l.nama_level
WHERE NOT EXISTS (
  SELECT 1 FROM kata_acuan k
  WHERE k.id_level = l.id_level AND k.hanzi = x.hanzi AND k.pinyin = x.pinyin
);
